function run(cb) {
  const output = [];
  for (let y = 0; y < context.output.y; y++) {
    const row = [];
    for (let x = 0; x < context.output.x; x++) {
      context.thread.y = y;
      context.thread.x = x;
      row.push(cb());
    }
    output.push(row);
  }
  return output;
}

