function vDwToArray(v) {
  const output = [];
  for (let y = 0; y < v.sy; y++) {
    const row = [];
    for (let x = 0; x < v.sx; x++) {
      row.push(v.get_grad(x, y, 0));
    }
    output.push(row);
  }

  return output;
}

function translateContextForward(context, filters, biases) {
  filters = translateInputs3D(filters);
  return {
    out_sx: context.output.x,
    out_sy: context.output.y,
    out_depth: context.output.z,
    stride: context.constants.strideX,
    pad: context.constants.paddingX,
    filters: [filters],
    biases: translateInputs1D(biases)
  }
}

function translateInputs3D(inputs) {
  const depth = inputs.length;
  const height = inputs[0].length;
  const width = inputs[0][0].length;
  const vol = new convnet.Vol(width, height, depth, 0);
  for (let z = 0; z < depth; z++) {
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        vol.set(x, y, z, inputs[z][y][x]);
      }
    }
  }
  return vol;
}

function translateInputs2D(inputs) {
  const height = inputs.length;
  const width = inputs[0].length;
  const vol = new convnet.Vol(width, height, 1, 0);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      vol.set(x, y, 0, inputs[y][x]);
    }
  }
  return vol;
}

function translateInputs1D(inputs) {
  const width = inputs.length;
  const vol = new convnet.Vol(width, 1, 1, 0);
  for (let x = 0; x < width; x++) {
    vol.set(x, 0, 0, inputs[x]);
  }
  return vol;
}